        ["Riavvia DeckyLoader e Steam"] = V("Restart DeckyLoader and Steam", "Reiniciar DeckyLoader y Steam", "Redémarrer DeckyLoader et Steam", "DeckyLoader und Steam neu starten", "Reiniciar DeckyLoader e Steam", "Перезапустити DeckyLoader і Steam", "重启 DeckyLoader 和 Steam", "DeckyLoader と Steam を再起動", "DeckyLoader와 Steam 다시 시작", "DeckyLoader और Steam फिर शुरू करें", "Перезапустить DeckyLoader и Steam"),
